# Formbricks start contract. .railway/railway.ts joins the non-comment lines with
# "; " into the Railway start command and compose.yaml runs this file, so every
# line must be a complete command and no command line may contain a single quote.
# It replaces the image's /home/nextjs/start.sh and keeps its steps in order.
# 1. Validate the owner address and the generated owner password before they reach JSON. Formbricks requires a capital letter and a digit.
owner=$(printf "%s" "${FORMBRICKS_OWNER_EMAIL:-}" | tr -d " \t\r" | tr "A-Z" "a-z")
case "$owner" in ""|*[!a-z0-9._%+@-]*) echo "Refusing to start: set FORMBRICKS_OWNER_EMAIL to the email address of the first administrator." >&2; exit 64;; esac
if ! printf "%s" "$owner" | grep -Eq "^[a-z0-9._%+-]+@[a-z0-9-]+([.][a-z0-9-]+)*[.][a-z]{2,}$"; then echo "Refusing to start: FORMBRICKS_OWNER_EMAIL is not a plain email address." >&2; exit 64; fi
if [ "$owner" = "bootstrap-sentinel@formbricks.invalid" ]; then echo "Refusing to start: FORMBRICKS_OWNER_EMAIL is reserved for the sign-up sentinel." >&2; exit 64; fi
case "${FORMBRICKS_OWNER_PASSWORD:-}" in ""|*[!A-Za-z0-9]*) echo "Refusing to start: FORMBRICKS_OWNER_PASSWORD must be letters and digits." >&2; exit 64;; esac
case "$FORMBRICKS_OWNER_PASSWORD" in *[A-Z]*) ;; *) echo "Refusing to start: FORMBRICKS_OWNER_PASSWORD needs a capital letter." >&2; exit 64;; esac
case "$FORMBRICKS_OWNER_PASSWORD" in *[0-9]*) ;; *) echo "Refusing to start: FORMBRICKS_OWNER_PASSWORD needs a digit." >&2; exit 64;; esac
if [ "${#FORMBRICKS_OWNER_PASSWORD}" -lt 16 ] || [ "${#FORMBRICKS_OWNER_PASSWORD}" -gt 128 ]; then echo "Refusing to start: FORMBRICKS_OWNER_PASSWORD must have 16 to 128 characters." >&2; exit 64; fi
# 2. Upstream environment validation, as in start.sh.
export NODE_ENV=production
node /home/nextjs/validate-env.mjs --server
# 3. Wait for PostgreSQL, then run the migration and SAML steps of start.sh.
db_host=$(printf "%s" "$DATABASE_URL" | sed -E "s#^[a-z]+://[^@]*@([^:/?]+).*#\1#")
until nc -z -w 3 "$db_host" 5432; do echo "Waiting for PostgreSQL"; sleep 2; done
timeout 300 node packages/database/dist/scripts/apply-migrations.js
timeout 60 node packages/database/dist/scripts/create-saml-database.js
# 4. Write the Formbricks authorization schema to SpiceDB (upstream authzed-initialize), retrying while SpiceDB starts.
n=0; until formbricks-authzed upgrade prepare; do n=$((n + 1)); if [ "$n" -ge 60 ]; then echo "Formbricks could not prepare SpiceDB." >&2; exit 1; fi; echo "Waiting for SpiceDB"; sleep 5; done
# 5. Classify the instance before any listener opens with scripts/formbricks-guard.cjs (embedded as base64 because Railway cannot mount files; verify.sh checks that they match). Formbricks admits an uninvited sign-up whenever its User table is empty. Step 8 inserts a deactivated sentinel user (no credential, no membership) before the public listener ever opens and nothing removes it, so the table cannot empty while any deployment is public, even if the owner deletes their account. Until the sentinel exists no listener has been public, so the guard removes rows an interrupted bootstrap left without a credential and reports fresh when none remain.
printf "%s" "" | base64 -d > /tmp/formbricks-guard.cjs
state=$(node /tmp/formbricks-guard.cjs pre)
# 6. Provisioning boot: Formbricks listens on loopback only, unreachable by Railway's proxy, health check and other services.
HOSTNAME=127.0.0.1 env -u FORMBRICKS_OWNER_PASSWORD node apps/web/online-server.js & pid=$!
trap "kill -TERM $pid 2>/dev/null; exit 143" TERM INT
until wget -q -O /dev/null "http://127.0.0.1:${PORT}/health/ready"; do if ! kill -0 "$pid" 2>/dev/null; then echo "Formbricks exited during the provisioning boot." >&2; exit 1; fi; sleep 2; done
# 7. Fresh instance only: create the owner through Formbricks own sign-up action, found by name in the build manifest (a fresh instance admits exactly one uninvited sign-up), then prove the credential by signing in on loopback. Request bodies with the password live in 0600 files, never in arguments.
umask 077
[ "$state" != fresh ] || action=$(node -e "const [file, name, source] = process.argv.slice(1); const actions = require(file).node; const ids = Object.keys(actions).filter((id) => actions[id].exportedName === name && actions[id].filename === source); if (ids.length !== 1) process.exit(1); console.log(ids[0]);" /home/nextjs/apps/web/.next/server/server-reference-manifest.json createUserAction apps/web/modules/auth/signup/actions.ts)
[ "$state" != fresh ] || printf "[{\"name\":\"Owner\",\"email\":\"%s\",\"password\":\"%s\"}]" "$owner" "$FORMBRICKS_OWNER_PASSWORD" > /tmp/formbricks-owner.json
[ "$state" != fresh ] || wget -q -O /tmp/formbricks-owner.out --header "Next-Action: $action" --header "Accept: text/x-component" --header "Content-Type: text/plain;charset=UTF-8" --header "Origin: http://127.0.0.1:${PORT}" --post-file /tmp/formbricks-owner.json "http://127.0.0.1:${PORT}/setup/signup" || true
rm -f /tmp/formbricks-owner.json
[ "$state" != fresh ] || grep -q "\"data\":{\"success\":true}" /tmp/formbricks-owner.out 2>/dev/null || { echo "Owner bootstrap failed; stopping." >&2; kill -TERM "$pid"; wait "$pid" || true; exit 1; }
rm -f /tmp/formbricks-owner.out
[ "$state" != fresh ] || printf "{\"email\":\"%s\",\"password\":\"%s\"}" "$owner" "$FORMBRICKS_OWNER_PASSWORD" > /tmp/formbricks-signin.json
[ "$state" != fresh ] || wget -q -O /dev/null --header "Content-Type: application/json" --post-file /tmp/formbricks-signin.json "http://127.0.0.1:${PORT}/api/auth/sign-in/email" || { rm -f /tmp/formbricks-signin.json; echo "The new owner account cannot sign in; stopping." >&2; kill -TERM "$pid"; wait "$pid" || true; exit 1; }
rm -f /tmp/formbricks-signin.json
# 8. Insert the sentinel before any public listener exists (see step 5), then stop the provisioning boot.
node /tmp/formbricks-guard.cjs post
[ "$state" = fresh ] && echo "Created the Formbricks owner account for $owner." || echo "Formbricks already has an owner account."
kill -TERM "$pid" 2>/dev/null || true; wait "$pid" || true
trap - TERM INT
# 9. Public boot on HOSTNAME (::) without the owner password.
exec env -u FORMBRICKS_OWNER_PASSWORD node apps/web/online-server.js
